<?php require __DIR__.'/app/bootstrap.php';$token=(string)($_GET['token']??'');$order=preg_match('/^[a-f0-9]{64}$/',$token)?query('SELECT * FROM orders WHERE access_token=?',[$token])->fetch():false;if(!$order){http_response_code(404);render_header('Order not found');echo '<main class="page"><h1>Order not found.</h1></main>';render_footer();exit;}$lines=query('SELECT * FROM order_items WHERE order_id=?',[$order['id']])->fetchAll();render_header('Order '.$order['reference']);?>
<main class="page narrow"><p class="eyebrow">THANK YOU FOR CHOOSING FLAWED</p><h1>Your order.<br><em>Your story.</em></h1><p class="notice">Order request received. Status: <strong><?=h(ucfirst($order['status']))?></strong></p><h2><?=h($order['reference'])?></h2><?php $shipment=query('SELECT consignment_id,tracking_url FROM shipments WHERE order_id=?',[$order['id']])->fetch();if($shipment):?><p>Pathao consignment: <strong><?=h($shipment['consignment_id'])?></strong><?php if($shipment['tracking_url']):?> · <a href="<?=h($shipment['tracking_url'])?>" target="_blank" rel="noopener noreferrer">Track with Pathao ↗</a><?php endif ?></p><?php endif ?><p>Save this private page to check your order status. Anyone with this link can view this order summary, so keep it private.</p><div class="summary-box"><?php foreach($lines as $line):?><div class="summary-line"><span><?=h($line['product_name'])?> / <?=h($line['size'])?> × <?=h($line['quantity'])?></span><strong><?=money($line['unit_price']*$line['quantity'])?></strong></div><?php endforeach ?><?php $discount=order_discount((int)$order['id']);if($discount):?><div class="summary-line"><span>Discount</span><strong>−<?=money($discount)?></strong></div><?php endif ?><div class="summary-line"><span>Delivery</span><strong><?=$order['delivery_fee']===null?'To be confirmed':money($order['delivery_fee'])?></strong></div><div class="summary-line total"><span><?=$order['total']===null?'Products after discount':'Total'?></span><strong><?=money($order['total']??($order['subtotal']-$discount))?></strong></div><p>Cash on delivery · <?=h($order['payment_status'])?></p><p>The team will contact you to confirm availability and delivery before dispatch. If you provided an email, an order acknowledgment will be sent when the store’s email connection is active. Keep this page as your order record.</p></div><?php if($order['status']==='delivered'):?><a class="button outline" href="<?=url('review.php?token='.$token)?>">REVIEW YOUR PURCHASE</a><?php endif ?><a class="button dark" href="<?=url('index.php#shop')?>">CONTINUE EXPLORING ↗</a></main><?php render_footer(); ?>
